import sys,socket,errno,json
sys.path.insert(0,"/workspace/onSkin/scripts/security_readiness/m103")
from sandbox import deny_network
held=[socket.socket(f,socket.SOCK_STREAM) for f in (socket.AF_INET,socket.AF_INET6)]
