checks=[]
for s in held:
 addr=("127.0.0.1",9) if s.family==socket.AF_INET else ("::1",9)
 for method,args in [("connect",(addr,)),("bind",(addr,)),("listen",(1,))]:
  try:getattr(s,method)(*args)
  except OSError as e:assert e.errno==errno.EPERM,(method,e);checks.append([str(s.family),method,e.errno])
  else:raise AssertionError(method+" permitted")
for f in (socket.AF_INET,socket.AF_INET6):
 try:socket.socket(f,socket.SOCK_STREAM)
 except OSError as e:assert e.errno==errno.EPERM;checks.append([str(f),"socket",e.errno])
 else:raise AssertionError("socket permitted")
